HZ = 150
STILL_SPEED, WINDOW_S = 0.005, 0.30            # strict still window (rad/s, s)
LOOSE_SPEED, LOOSE_WINDOW_S = 0.02, 0.20       # the module's own settled speed
TIMEOUT_S = 6.0
H = {"events": [], "arm": None, "S": None, "cmd": None}


def descendants(model, root):
    ids = {model.body(root).id}
    for b in range(model.nbody):
        p = b
        while p:
            if p in ids:
                ids.add(b)
                break
            p = int(model.body_parentid[p])
    return ids


def make_hook():
    def hook(modules, model, data):
        m = modules["manipulation"]
        S, arm = m["state"], m["arm"]
        H["arm"], H["S"] = arm, S
        step0, arm_step0 = m["step"], arm.step

        def arm_step(d, position, rotation):                 # the commanded pad pose (the waypoint plus the sag correction), for 1b
            H["cmd"] = (np.array(position, float), np.array(rotation, float))
            return arm_step0(d, position, rotation)
        arm.step = arm_step

        def step(obs):
            i0 = S["i"]
            st = S["steps"][i0] if S["steps"] and i0 < len(S["steps"]) else None
            t0 = S["t0"]
            out = step0(obs)
            if st is not None and S["i"] > i0:
                T = st.get("T")
                H["events"].append({"prim": S["ctx"].get("primitive"), "name": st["name"], "kind": st["kind"], "t": float(obs["time"]), "last": S["i"] >= len(S["steps"]),
                                    "motion_end": None if (T is None or t0 is None) else float(t0 + T)})
            return out
        m["step"] = step
        return modules
    return hook


def unit_angle(a, b):
    return float(np.degrees(np.arccos(np.clip(a @ b / max(np.linalg.norm(a) * np.linalg.norm(b), 1e-12), -1, 1))))


def make_sampler(model, data):
    arm_name = TASK_CFG["arm"]
    aid = [mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, f"{arm_name}_joint{i}_ctrl") for i in range(1, 8)]
    gaid = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, f"{arm_name}_gripper_ctrl")
    cap = np.array([robot_specs.ARM_ACTUATOR_SPECS["joints"][i]["torque_nm"] for i in range(1, 8)])
    jr = np.array([model.jnt_range[model.joint(f"openarm_{arm_name}_joint{i}").id] for i in range(1, 8)])
    fq = int(model.joint(f"openarm_{arm_name}_finger_joint1").qposadr[0])
    gff = ArmGravityFeedforward.from_model(model)
    bb = model.body("task_beaker").id
    beaker = descendants(model, "task_beaker")
    plate = descendants(model, "task_hotplate")
    bg = {g for g in range(model.ngeom) if int(model.geom_bodyid[g]) in beaker}
    hg = {g for g in range(model.ngeom) if int(model.geom_bodyid[g]) in plate and (model.geom_contype[g] or model.geom_conaffinity[g])}
    fgL = {g for g in range(model.ngeom) if model.body(int(model.geom_bodyid[g])).name == f"openarm_{arm_name}_left_finger" and (model.geom_contype[g] or model.geom_conaffinity[g])}
    fgR = {g for g in range(model.ngeom) if model.body(int(model.geom_bodyid[g])).name == f"openarm_{arm_name}_right_finger" and (model.geom_contype[g] or model.geom_conaffinity[g])}
    plate_top = float(data.site("hotplate_top").xpos[2])
    f6 = np.zeros(6)
    dt = 1.0 / HZ
    R = {"rows": [], "t": [], "qd": [], "q": [], "tau": [], "done": 0, "pending": [], "readings": [], "base": None, "prev_pad": None, "first_plate": None, "loss": None,
         "series": [], "down": {"rows": []}, "recov": []}

    def contacts(axis, bpos):
        """Per finger: normal force sum, force-weighted contact position and inward normal; the beaker-hotplate normal force and the closest approach."""
        fin = {"L": {"F": 0.0, "pos": np.zeros(3), "n": np.zeros(3), "k": 0}, "R": {"F": 0.0, "pos": np.zeros(3), "n": np.zeros(3), "k": 0}}
        plate_F = 0.0
        for i in range(data.ncon):
            c = data.contact[i]
            a, b = int(c.geom1), int(c.geom2)
            if (a in bg) == (b in bg):
                continue
            mine, other = (a, b) if a in bg else (b, a)
            mujoco.mj_contactForce(model, data, i, f6)
            Fn = float(f6[0])
            nvec = np.array(c.frame[:3])
            if a in bg:                                         # the normal points from geom1 to geom2; make it point from the finger into the beaker
                nvec = nvec
            else:
                nvec = -nvec
            nvec = -nvec if False else nvec
            if other in fgL or other in fgR:
                key = "L" if other in fgL else "R"
                fin[key]["F"] += Fn
                fin[key]["pos"] += Fn * np.array(c.pos)
                fin[key]["n"] += Fn * (-nvec)                  # from the finger into the beaker (nvec points from the beaker to the other geom here)
                fin[key]["k"] += 1
            elif other in hg:
                plate_F += Fn
        out = {}
        for key, v in fin.items():
            if v["F"] > 1e-9:
                pos = v["pos"] / v["F"]
                rel = pos - bpos
                h = float(rel @ axis)
                lat = rel - h * axis
                out[key] = {"F": v["F"], "h_mm": 1000 * h, "lat_mm": 1000 * float(np.linalg.norm(lat)), "lat": lat, "n": v["n"] / max(np.linalg.norm(v["n"]), 1e-12)}
            else:
                out[key] = {"F": 0.0}
        return out, plate_F

    def facing(c):
        """Do the two contacts face each other through the centre: angle between their directions seen from the axis (180 = opposite), the chord's distance from the axis, the angle between the normals."""
        if "lat" not in c["L"] or "lat" not in c["R"]:
            return None
        l1, l2 = c["L"]["lat"], c["R"]["lat"]
        chord = float(np.linalg.norm(l1 - l2))
        return {"angle_deg": unit_angle(l1, l2), "chord_offset_mm": 1000 * float(np.linalg.norm(np.cross(l1, l2))) / max(chord, 1e-9), "normals_angle_deg": unit_angle(c["L"]["n"], c["R"]["n"])}

    def key_now(point, Rp):
        com = data.xipos[bb]
        return {"com_rel_pad_world_m": [float(x) for x in (com - point)], "com_rel_pad_pad_frame_m": [float(x) for x in Rp.T @ (com - point)]}

    def measure(label, ev, thr, win_s, strict):
        n = int(round(win_s * HZ))
        if len(R["t"]) < n:
            return False
        qd = np.abs(np.array(R["qd"][-n:])).max(axis=1)
        if np.any(qd >= thr):
            return False
        q = np.mean(R["q"][-n:], axis=0)
        tau = np.mean(R["tau"][-n:], axis=0)
        res = hand_load_with_balance_point(model, q, tau, H["arm"], gff)
        p, Rp = H["arm"].pad_pose(data)
        allqd = np.abs(np.array(R["qd"])).max(axis=1)
        k = len(allqd)
        while k > 0 and allqd[k - 1] < thr:
            k -= 1
        rec = {"label": label, "strict": strict, "event": ev["name"], "trigger_t": ev["t"], "reading_t": R["t"][-1], "still_since_t": float(R["t"][min(k, len(R["t"]) - 1)]), "window_s": win_s,
               "speed_threshold": thr, "max_speed_in_window": float(qd.max()), "mass_kg": res["mass_kg"], "mass_down_only_kg": res["mass_down_only_kg"], "offset_world_xy_m": res["offset_world_xy_m"],
               "offset_pad_frame_m": res["offset_pad_frame_m"], "unexplained": res["unexplained"], "unexplained_down_only": res["unexplained_down_only"], "extra_nm": [float(x) for x in res["extra_nm"]],
               "answer_key": key_now(p, Rp)}
        R["readings"].append(rec)
        return True

    def step(obs):
        arm, S = H["arm"], H["S"]
        if arm is None:
            return None
        t = float(data.time)
        R["t"].append(t)
        R["qd"].append(data.qvel[arm.vadr].copy())
        R["q"].append(data.qpos.copy())
        R["tau"].append(data.actuator_force[aid].copy())
        steps = S.get("steps") or []
        cur = steps[S["i"]] if S.get("i") is not None and S["i"] < len(steps) else None
        prim = S["ctx"].get("primitive")
        label = f"{prim}:{cur['name']}" if cur is not None else f"{prim}:-"
        p, Rp = arm.pad_pose(data)
        speed = 0.0 if R["prev_pad"] is None else float(np.linalg.norm(p - R["prev_pad"]) / dt)
        R["prev_pad"] = p.copy()
        # 1a / 1b: the beaker
        Rb = data.xmat[bb].reshape(3, 3)
        axis = Rb[:, 2].copy()
        bpos = data.xpos[bb].copy()
        tilt = float(np.degrees(np.arccos(np.clip(axis[2], -1, 1))))
        dpb = Rb.T @ (p - bpos)                                  # the pad centre in the beaker's frame: z along the axis
        cs, plate_F = contacts(axis, bpos)
        if label == "pick:CLOSE" and R["base"] is None:
            R["base"] = dpb.copy()
        dz = dl = None
        if R["base"] is not None:
            dz = 1000 * float(dpb[2] - R["base"][2])
            dl = 1000 * float(np.linalg.norm(dpb[:2] - R["base"][:2]))
        row = {"t": t, "label": label, "tilt": tilt, "dz": dz, "dl": dl, "FL": cs["L"]["F"], "FR": cs["R"]["F"], "hL": cs["L"].get("h_mm"), "hR": cs["R"].get("h_mm"), "latL": cs["L"].get("lat_mm"),
               "latR": cs["R"].get("lat_mm"), "face": facing(cs), "grip_act": float(data.actuator_force[gaid]), "finger": float(data.qpos[fq]), "speed": speed, "plate_F": plate_F,
               "bottom_clear_mm": 1000 * float(bpos[2] - plate_top), "beaker_pad_mm": 1000 * float(np.linalg.norm(p - bpos))}
        R["rows"].append(row)
        # 1b: during the place's DOWN and OVER
        if cur is not None and prim == "place" and cur["name"] in ("OVER", "DOWN") and "target" in cur:
            err = p - cur["target"]
            cmd = H["cmd"]
            Cp = Cr = None
            if cmd is not None:
                Cp = float(np.linalg.norm(cmd[0] - cur["target"]))
                Cr = float(np.linalg.norm(Rotation.from_matrix(cmd[1] @ cur["R"].T).as_rotvec()))
            q = data.qpos[arm.qadr]
            lim = np.minimum(q - jr[:, 0], jr[:, 1] - q)
            bound = lim - robot_specs.PICK_PLACE_CFG["joint_margin_rad"] if "joint_margin_rad" in getattr(robot_specs, "PICK_PLACE_CFG", {}) else lim - math.radians(10.0)
            share = np.abs(data.actuator_force[aid]) / cap
            R["down"]["rows"].append({"t": t, "step": cur["name"], "err_mm": [1000 * float(x) for x in err], "err_norm_mm": 1000 * float(np.linalg.norm(err)), "Cp_m": Cp, "Cr_rad": Cr, "min_limit_margin_rad": float(lim.min()),
                                      "min_limit_joint": int(np.argmin(lim)) + 1, "min_solver_bound_margin_rad": float(bound.min()), "max_torque_share": float(share.max()), "max_torque_joint": int(np.argmax(share)) + 1})
            if plate_F > 1e-6 and R["first_plate"] is None:
                R["first_plate"] = {"t": t, "step": cur["name"], "hand_err_mm": [1000 * float(x) for x in err], "hand_err_norm_mm": 1000 * float(np.linalg.norm(err)), "bottom_clear_mm": row["bottom_clear_mm"], "plate_F": plate_F}
        # 1b: the recovery
        if prim == "recover":
            R["recov"].append({"t": t, "label": label, "speed": speed, "FL": cs["L"]["F"], "FR": cs["R"]["F"], "finger": row["finger"], "beaker_pad_mm": row["beaker_pad_mm"], "joint_speed": float(np.abs(data.qvel[arm.vadr]).max())})
            if R["loss"] is None and len(R["recov"]) > 10:
                held_before = any(r["FL"] + r["FR"] > 0.5 for r in R["recov"][:-1])
                if held_before and cs["L"]["F"] + cs["R"]["F"] < 0.05:
                    recent = R["recov"][-30:]
                    R["loss"] = {"t": t, "label": label, "pad_speed_m_s": speed, "peak_pad_speed_last_0.2s_m_s": max(r["speed"] for r in recent), "joint_speed_rad_s": R["recov"][-1]["joint_speed"], "finger_opening_m": row["finger"]}
        if len(R["rows"]) % 15 == 0:
            R["series"].append({k: (round(v, 4) if isinstance(v, float) else v) for k, v in row.items() if k != "face"})
        # 1c: readings at the handoffs
        while R["done"] < len(H["events"]):
            ev = H["events"][R["done"]]
            R["done"] += 1
            if ev["last"] and ev["prim"] in ("pick", "place"):
                R["pending"].append((f"{ev['prim']} handoff, strict still", ev, STILL_SPEED, WINDOW_S, True))
                R["pending"].append((f"{ev['prim']} handoff, loose still (module's settled speed)", ev, LOOSE_SPEED, LOOSE_WINDOW_S, False))
            elif ev["prim"] == "place" and ev["name"] == "BACK":
                R["pending"].append(("place, end of BACK, loose still", ev, LOOSE_SPEED, LOOSE_WINDOW_S, False))
        keep = []
        for item in R["pending"]:
            lab, ev, thr, win, strict = item
            if measure(lab, ev, thr, win, strict):
                continue
            if t - ev["t"] > TIMEOUT_S:
                R["readings"].append({"label": lab, "strict": strict, "event": ev["name"], "trigger_t": ev["t"], "failed": f"not still for {win} s below {thr} rad/s within {TIMEOUT_S} s"})
                continue
            keep.append(item)
        R["pending"] = keep
        return None
    return {"name": "grip_sampler", "step": step, "state": R}


def phase_group(label):
    if label == "pick:CLOSE":
        return "closing"
    if label in ("pick:UP", "pick:CHECK"):
        return "lift"
    if label in ("place:OVER", "place:DOWN"):
        return "carry"
    return None


def summarize(R):
    rows = R["rows"]
    out = {"phases": {}, "samples": {}}
    for grp in ("closing", "lift", "carry"):
        rs = [r for r in rows if phase_group(r["label"]) == grp and r["dz"] is not None]
        if not rs:
            continue
        out["phases"][grp] = {"t0": rs[0]["t"], "t1": rs[-1]["t"], "max_tilt_deg": max(r["tilt"] for r in rs), "tilt_end_deg": rs[-1]["tilt"], "max_slide_axial_mm": max(abs(r["dz"]) for r in rs),
                              "slide_axial_end_mm": rs[-1]["dz"], "max_slide_sideways_mm": max(r["dl"] for r in rs), "slide_sideways_end_mm": rs[-1]["dl"], "max_normal_force_L_N": max(r["FL"] for r in rs),
                              "max_normal_force_R_N": max(r["FR"] for r in rs)}
    def at(label_pred, last=True):
        rs = [r for r in rows if label_pred(r["label"])]
        if not rs:
            return None
        sel = rs[-10:] if last else rs[:10]
        return {"t": sel[-1]["t"], "FL_N": float(np.mean([r["FL"] for r in sel])), "FR_N": float(np.mean([r["FR"] for r in sel])), "hL_mm": sel[-1]["hL"], "hR_mm": sel[-1]["hR"], "latL_mm": sel[-1]["latL"],
                "latR_mm": sel[-1]["latR"], "face": sel[-1]["face"], "gripper_actuator_N": float(np.mean([r["grip_act"] for r in sel])), "finger_opening_m": sel[-1]["finger"], "tilt_deg": sel[-1]["tilt"]}
    out["samples"]["end_of_closing"] = at(lambda l: l == "pick:CLOSE")
    out["samples"]["end_of_lift"] = at(lambda l: l in ("pick:UP", "pick:CHECK"))
    out["samples"]["end_of_place_DOWN"] = at(lambda l: l == "place:DOWN")
    return out


def main(args):
    cfg = {**BEAKER_CFG, "liquid_mass": args.liquid}
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    task = make_pipeline_task(PLAN4, module_hook=make_hook())
    gc.collect()
    sim = load_task(TASK_CFG, cameras=True, beaker_cfg=cfg)
    holder = {}

    def extra(m, d):
        holder["s"] = make_sampler(m, d)
        return {"grip_sampler": holder["s"]}
    s = run_episode(task, sim.model, sim.data, out_dir=out / "episode", extra_sources=extra, stop_after_handoff_s=None)
    state = task["pipeline"]["orchestrator"]["state"]
    ok, _ = task["check_success"](sim.model, sim.data)
    true_kg = float(sim.model.body_mass[sim.model.body("task_beaker").id])          # the answer key, read only now
    R = holder["s"]["state"]
    summ = summarize(R)
    down_rows = R["down"]["rows"]
    res = {"liquid_kg": args.liquid, "true_total_kg": true_kg, "grip_force_cap_N_per_finger": GRIP_FORCE_TABLE["glass_beaker"], "outcome": s["outcome"], "failure": state["failure"], "status": state["status"],
           "beaker_on_hotplate": bool(ok), "grip": summ, "first_plate_contact": R["first_plate"], "recovery_loss": R["loss"], "readings": R["readings"],
           "down_series": down_rows[::15], "down_last": down_rows[-1] if down_rows else None, "recovery_series": R["recov"][::5], "series": R["series"],
           "sag_caps": {"sag_max_m": PICK_PLACE_CFG["sag_max_m"], "sag_max_rad": PICK_PLACE_CFG["sag_max_rad"], "tol_m": PICK_PLACE_CFG["tol_m"], "tol_rad": PICK_PLACE_CFG["tol_rad"]}}
    tmp = out / "result.json.tmp"
    tmp.write_text(json.dumps(res, indent=1, default=str))
    tmp.replace(out / "result.json")
    print(f"true total {1000 * true_kg:.0f} g; outcome {s['outcome']}; failure {state['failure']}", flush=True)
    for g, v in summ["phases"].items():
        print(f"  {g}: max tilt {v['max_tilt_deg']:.1f} deg, axial slide {v['max_slide_axial_mm']:.1f} mm, sideways {v['max_slide_sideways_mm']:.1f} mm", flush=True)
    for r in R["readings"]:
        print("  reading", r["label"], "FAILED" if "failed" in r else f"{1000 * r['mass_kg']:.1f} g (down-only {1000 * r['mass_down_only_kg']:.1f}), unexplained {100 * r['unexplained']:.0f} % vs {100 * r['unexplained_down_only']:.0f} %", flush=True)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--liquid", type=float, required=True)
    ap.add_argument("--out", required=True)
    main(ap.parse_args())
